import os
import hashlib
import hmac
import secrets
from flask import Flask, request, abort, send_file, session, jsonify
from functools import wraps
from urllib.parse import unquote
import re

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

UPLOAD_DIR = '/var/app/uploads'
SECRET_SIGNING_KEY = os.environ.get('SIGNING_KEY', secrets.token_hex(32))

def generate_file_token(username, filepath):
    """Generate HMAC token for authorized file access"""
    msg = f"{username}:{filepath}".encode('utf-8')
    return hmac.new(SECRET_SIGNING_KEY.encode(), msg, hashlib.sha256).hexdigest()

def verify_file_token(username, filepath, token):
    """Verify HMAC token for file access authorization"""
    expected = generate_file_token(username, filepath)
    return hmac.compare_digest(expected, token)

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'username' not in session:
            abort(401)
        return f(*args, **kwargs)
    return decorated

def sanitize_path(user_path):
    """Sanitize file path to prevent directory traversal.

    Strategy: normalize the path, then verify it stays within bounds.
    We decode percent-encoding first since paths may come URL-encoded.
    """
    # Decode any percent-encoding in the path
    decoded_path = unquote(user_path)

    # Normalize the path to resolve any ../ sequences
    normalized = os.path.normpath(decoded_path)

    # Security check: ensure no path traversal components remain
    # after normalization
    if normalized.startswith('/') or normalized.startswith('..'):
        return None

    # Additional check: no null bytes
    if '\x00' in normalized:
        return None

    # Build the full path
    full_path = os.path.join(UPLOAD_DIR, normalized)

    # Final containment check - verify resolved path is under UPLOAD_DIR
    # Use normpath to resolve the joined path
    resolved = os.path.normpath(full_path)
    if not resolved.startswith(UPLOAD_DIR):
        return None

    return resolved

def sanitize_path_for_token(user_path):
    """Sanitize path specifically for token generation/verification.

    This must match exactly what the token was generated against.
    We normalize but preserve the semantic path for token matching.
    """
    # For token purposes, we normalize the raw path
    # This ensures tokens match regardless of encoding variations
    normalized = os.path.normpath(user_path)
    if normalized.startswith('/') or normalized.startswith('..'):
        return None
    return normalized

@app.route('/api/files/token', methods=['POST'])
@require_auth
def get_file_token():
    """Get a signed token to access a specific file"""
    filepath = request.json.get('filepath', '')

    # Sanitize for token generation
    clean_path = sanitize_path_for_token(filepath)
    if clean_path is None:
        abort(400)

    # Verify file exists
    full = os.path.join(UPLOAD_DIR, clean_path)
    if not os.path.isfile(full):
        abort(404)

    token = generate_file_token(session['username'], clean_path)
    return jsonify({'token': token, 'path': clean_path})

@app.route('/api/files/download')
@require_auth
def download_file():
    """Download a file with token-based authorization.

    The token proves the user was authorized to access this specific path.
    Path is verified for traversal attacks before serving.
    """
    filepath = request.args.get('path', '')
    token = request.args.get('token', '')

    if not filepath or not token:
        abort(400)

    # Verify the token against the NORMALIZED path for consistency
    # Token was generated against normalized path, so verify against same
    token_path = sanitize_path_for_token(filepath)
    if token_path is None:
        abort(400)

    if not verify_file_token(session['username'], token_path, token):
        abort(403)

    # Now sanitize the actual requested path for filesystem access
    # This uses the full sanitization pipeline
    safe_path = sanitize_path(filepath)
    if safe_path is None:
        abort(400)

    return send_file(safe_path)

@app.route('/api/files/serve/<path:filepath>')
@require_auth  
def serve_file(filepath):
    """Serve a file directly (for authenticated users' own uploads).

    Uses path sanitization to prevent traversal.
    """
    safe_path = sanitize_path(filepath)
    if safe_path is None:
        abort(403)

    # Verify the file belongs to the user's directory
    user_dir = os.path.join(UPLOAD_DIR, session['username'])
    user_dir_resolved = os.path.normpath(user_dir)
    if not safe_path.startswith(user_dir_resolved):
        abort(403)

    if not os.path.isfile(safe_path):
        abort(404)

    return send_file(safe_path)

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
